INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$بَارَكَ اللَّهُ لَكَ فِي الْمَوْهُوبِ لَكَ، وَشَكَرْتَ الْوَاهِبَ، وَبَلَغَ أَشُدَّهُ، وَرُزِقْتَ بِرَّهُ$q$, $q$Baraka llahou laka fi l-mawhoubi laka, wachakarta l-wahiba, wabalagha achouddahou, warouziqta birrah$q$, $q$Qu’Allah te bénisse dans ce qui t’a été donné, que tu remercies Celui qui l’a donné, qu’il atteigne sa maturité et que tu sois comblé de sa bonté.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Félicitations pour une naissance », invocation n° 1. Formule rapportée par an-Nawawi, al-Adhkar p. 349 (voir Sahih al-Adhkar d’an-Nawawi, éd. Salim al-Hilali 2/713).$q$, 1, 800, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$بَارَكَ اللَّهُ لَكَ فِي الْمَوْهُوبِ لَكَ، وَشَكَرْتَ الْوَاهِبَ، وَبَلَغَ أَشُدَّهُ، وَرُزِقْتَ بِرَّهُ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$بَارَكَ اللَّهُ لَكَ وَبَارَكَ عَلَيْكَ، وَجَزَاكَ اللَّهُ خَيْراً، وَرَزَقَكَ اللَّهُ مِثْلَهُ، وَأَجْزَلَ ثَوَابَكَ$q$, $q$Baraka llahou laka wabaraka ʿalayka, wadjazaka llahou khayran, warazaqaka llahou mithlahou, wa’adjzala thawabak$q$, $q$Qu’Allah te bénisse et répande Sa bénédiction sur toi, qu’Il te récompense en bien, te donne la pareille et multiplie ta récompense. (réponse de celui que l’on félicite)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Félicitations pour une naissance », invocation n° 2. Formule rapportée par an-Nawawi, al-Adhkar p. 349 (voir Sahih al-Adhkar d’an-Nawawi, éd. Salim al-Hilali 2/713).$q$, 1, 801, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$بَارَكَ اللَّهُ لَكَ وَبَارَكَ عَلَيْكَ، وَجَزَاكَ اللَّهُ خَيْراً، وَرَزَقَكَ اللَّهُ مِثْلَهُ، وَأَجْزَلَ ثَوَابَكَ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لاَمَّةٍ$q$, $q$Ouʿidhoukouma bikalimati llahi t-tammati min koulli chaytanin wahammatin, wamin koulli ʿaynin lammah$q$, $q$Je vous place sous la protection des paroles parfaites d’Allah, contre tout démon et toute bête nuisible, et contre tout mauvais œil. (le Prophète protégeait ainsi al-Hasan et al-Husayn)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Protéger les enfants », invocation n° 1. Al-Bukhari 4/119, hadith d’Ibn ‘Abbas (qu’Allah les agrée).$q$, 1, 802, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لاَمَّةٍ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ$q$, $q$Baraka llahou laka, wabaraka ʿalayka, wadjamaʿa baynakouma fi khayr$q$, $q$Qu’Allah te bénisse, répande Sa bénédiction sur toi et vous réunisse dans le bien. (à dire à celui qui se marie)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Félicitations pour un mariage », invocation n° 1. Les auteurs des Sunan sauf an-Nasa’i (voir Sahih at-Tirmidhi 1/316).$q$, 1, 803, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا جَبَلْتَهَا عَلَيْهِ$q$, $q$Allahoumma inni as’alouka khayraha, wakhayra ma djabaltaha ʿalayhi, wa’aʿoudhou bika min charriha, wacharri ma djabaltaha ʿalayh$q$, $q$Ô Allah, je Te demande son bien et le bien de la nature que Tu lui as donnée, et je cherche refuge auprès de Toi contre son mal et le mal de la nature que Tu lui as donnée. (à dire en se mariant ou en achetant un serviteur ; pour un chameau, saisir le haut de sa bosse et dire la même chose)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Celui qui se marie », invocation n° 1. Abu Dawud 2/248 ; Ibn Majah 1/617 (voir Sahih Ibn Majah 1/324).$q$, 1, 804, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا جَبَلْتَهَا عَلَيْهِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$بِسْمِ اللَّهِ، اللَّهُمَّ جَنِّبْنَا الشَّيْطَانَ، وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا$q$, $q$Bismi llahi, Allahoumma djannibna ch-chaytana, wadjannibi ch-chaytana ma razaqtana$q$, $q$Au nom d’Allah. Ô Allah, éloigne de nous Satan et éloigne Satan de ce que Tu nous accordes.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Avant les rapports conjugaux », invocation n° 1. Al-Bukhari 6/141 ; Muslim 2/1028.$q$, 1, 805, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$بِسْمِ اللَّهِ، اللَّهُمَّ جَنِّبْنَا الشَّيْطَانَ، وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي مِمَّا ابْتَلاَكَ بِهِ، وَفَضَّلَنِي عَلَى كَثِيرٍ مِمَّنْ خَلَقَ تَفْضِيلاً$q$, $q$Al-hamdou lillahi-lladhi ʿafani mimma-btalaka bihi, wafaddalani ʿala kathirin mimman khalaqa tafdila$q$, $q$Louange à Allah qui m’a préservé de ce dont Il t’a éprouvé et m’a favorisé nettement sur beaucoup de ceux qu’Il a créés.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Quand on voit une personne éprouvée », invocation n° 1. At-Tirmidhi 5/494 et 5/493 (voir Sahih at-Tirmidhi 3/153).$q$, 1, 806, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي مِمَّا ابْتَلاَكَ بِهِ، وَفَضَّلَنِي عَلَى كَثِيرٍ مِمَّنْ خَلَقَ تَفْضِيلاً$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$رَبِّ اغْفِرْ لِي، وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ الْغَفُورُ$q$, $q$Rabbi-ghfir li, watoub ʿalayya, innaka anta t-tawwabou l-ghafour$q$, $q$Seigneur, pardonne-moi et accepte mon repentir, car Tu es Celui qui accepte le repentir, le Pardonneur. (Ibn ‘Umar : on comptait pour le Messager d’Allah, en une seule assemblée, une centaine de fois cette invocation avant qu’il se lève)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Pendant une assemblée », invocation n° 1. At-Tirmidhi (dont est la formulation) et d’autres (voir Sahih at-Tirmidhi 3/153 ; Sahih Ibn Majah 2/321). Le compteur est laissé à 1.$q$, 1, 807, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$رَبِّ اغْفِرْ لِي، وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ الْغَفُورُ$q$);

