INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$بَارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ، إِنَّمَا جَزَاءُ السَّلَفِ الْحَمْدُ وَالأَدَاءُ$q$, $q$Baraka llahou laka fi ahlika wamalika, innama djaza’ou s-salafi l-hamdou wal-ada’$q$, $q$Qu’Allah te bénisse dans ta famille et tes biens : la récompense d’un prêt est la louange et la restitution. (à dire à celui qui vous rembourse)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Pour celui qui vous rembourse un prêt », invocation n° 1. An-Nasa’i, ‘Amal al-yawm wa-l-layla p. 300 ; Ibn Majah 2/809 (voir Sahih Ibn Majah 2/55).$q$, 1, 812, false
