INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا لاَ أَعْلَمُ$q$, $q$Allahoumma inni aʿoudhou bika an ouchrika bika wa’ana aʿlamou, wa’astaghfirouka lima la aʿlam$q$, $q$Ô Allah, je cherche refuge auprès de Toi pour ne pas T’associer quoi que ce soit en le sachant, et je Te demande pardon pour ce que j’ignore.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Crainte de l’association (shirk) », invocation n° 1. Ahmad 4/403 et d’autres (voir Sahih al-Jami‘ 3/333 ; Sahih at-targhib wa-t-tarhib d’al-Albani).$q$, 1, 813, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا لاَ أَعْلَمُ$q$);

