INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ فَأَيُّمَا مُؤْمِنٍ سَبَبْتُهُ فَاجْعَلْ ذَلِكَ لَهُ قُرْبَةً إِلَيْكَ يَوْمَ الْقِيَامَةِ$q$, $q$Allahoumma fa’ayyouma mou’minin sababtouhou fadjʿal dhalika lahou qourbatan ilayka yawma l-qiyamah$q$, $q$Ô Allah, tout croyant que j’aurais insulté, fais-en pour lui un rapprochement de Toi au Jour de la Résurrection.$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Pour celui que l’on a insulté », invocation n° 1. Al-Bukhari, Fath al-Bari 11/171 ; Muslim 4/2007 (dont la version est : « fais-en pour lui une purification et une miséricorde »).$q$, 1, 815, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ فَأَيُّمَا مُؤْمِنٍ سَبَبْتُهُ فَاجْعَلْ ذَلِكَ لَهُ قُرْبَةً إِلَيْكَ يَوْمَ الْقِيَامَةِ$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$أَحْسِبُ فُلاَناً وَاللَّهُ حَسِيبُهُ، وَلاَ أُزَكِّي عَلَى اللَّهِ أَحَداً، أَحْسِبُهُ – إِنْ كَانَ يَعْلَمُ ذَاكَ – كَذَا وَكَذَا$q$, $q$Ahsibou foulanan wallahou hasibouhou, wala ouzakki ʿala llahi ahadan, ahsibouhou in kana yaʿlamou dhaka kadha wakadha$q$, $q$J’estime un tel (le nommer) ainsi ; Allah est Celui qui lui demandera des comptes, et je ne déclare personne pur devant Allah. Je l’estime — s’il en est bien ainsi — tel et tel (citer la qualité). (hadith : « Si l’un de vous doit absolument faire l’éloge de son compagnon, qu’il dise… »)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Quand on doit faire l’éloge de quelqu’un », invocation n° 1. Muslim 4/2296.$q$, 1, 816, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$أَحْسِبُ فُلاَناً وَاللَّهُ حَسِيبُهُ، وَلاَ أُزَكِّي عَلَى اللَّهِ أَحَداً، أَحْسِبُهُ – إِنْ كَانَ يَعْلَمُ ذَاكَ – كَذَا وَكَذَا$q$);

INSERT INTO athkar_items(category, text_ar, translit, tr_fr, tr_en, reference, target, position, enabled)
SELECT $q$general$q$, $q$اللَّهُمَّ لاَ تُؤَاخِذْنِي بِمَا يَقُولُونَ، وَاغْفِرْ لِي مَا لاَ يَعْلَمُونَ، وَاجْعَلْنِي خَيْراً مِمَّا يَظُّنُّونَ$q$, $q$Allahoumma la tou’akhidhni bima yaqoulouna, waghfir li ma la yaʿlamouna, wadjʿalni khayran mimma yadhdhounnoun$q$, $q$Ô Allah, ne me tiens pas rigueur de ce qu’ils disent, pardonne-moi ce qu’ils ignorent (et rends-moi meilleur que ce qu’ils pensent de moi). (à dire quand on est loué)$q$, $q$$q$, $q$Hisn al-Muslim (Sa‘id al-Qahtani), « Quand on est loué », invocation n° 1. Al-Bukhari, al-Adab al-mufrad n° 761 ; chaîne jugée authentique par al-Albani (Sahih al-Adab al-mufrad n° 585). L’ajout entre crochets est d’al-Bayhaqi, Shu‘ab al-iman 4/228, par une autre voie.$q$, 1, 817, false
WHERE NOT EXISTS (SELECT 1 FROM athkar_items WHERE category = $q$general$q$ AND text_ar = $q$اللَّهُمَّ لاَ تُؤَاخِذْنِي بِمَا يَقُولُونَ، وَاغْفِرْ لِي مَا لاَ يَعْلَمُونَ، وَاجْعَلْنِي خَيْراً مِمَّا يَظُّنُّونَ$q$);
